\label{a1} $H_\pm$ are two selfadjoint, short-range Hamiltonians on $\ell^2({\mathbb Z}^2,{\mathbb C}^d)$, with a common spectral gap ${\mathcal G}$ (an interval contained in $\Sigma(H_+)^c \cap \Sigma(H_-)^c$) and distinct bulk conductances within~${\mathcal G}$:
\begin{equation}
    \sigma(H_+,{\mathcal G}) \neq \sigma(H_-,{\mathcal G}).
\end{equation}

\label{a2} $H_e$ is a selfadjoint, short-range Hamiltonian on $\ell^2({\mathbb Z}^2,{\mathbb C}^d)$ satisfying the kernel condition: \begin{equation}\label{eq-1a}
\forall {\bm{x}}, {\bm{y}} \in {\mathbb Z}^2, \qquad
    \big| E({\bm{x}},{\bm{y}}) \big| \leq \nu^{-1} e^{-2\nu d({\bm{x}},\partial \Omega)}, \qquad E :=  H_e - \1_\Omega H_+ \1_\Omega - \1_{\Omega^c} H_- \1_{\Omega^c}.
\end{equation}

\label{a4}
    $H$ is a selfadjoint, short-range operator on $\ell^2({\mathbb Z}^2;{\mathbb C}^d)$, such that for some $\lambda \in {\mathbb R}$ and $\delta \in (0,1)$,
\begin{equation}
    (\lambda-\delta,\lambda+\delta) \cap \Sigma(H) = \emptyset.
\end{equation}

\label{prop:2} There exists a constant $C_\nu \geq 1$ such that the following holds. Let $\epsilon > 0$, $r > 0$, ${\textbf{n}} \in {\mathbb Z}^2$, and $H_1$, $H_2$ satisfy Assumption \ref{a4} such that 
    \begin{equation}
        \label{eq: H1_H2_coincide}
    |(H_1 - H_2)({\bm{x}},{\bm{y}})| \leq \epsilon, \quad {\bm{x}}, {\bm{y}} \in B_{4r}({\textbf{n}}).
    \end{equation}
    Then we have: 
    \begin{equation}
        \label{eq: sigma_B_locally_determined}
    |\sigma(H_1,\lambda) - \sigma(H_2,\lambda)|\leq \frac{C_\nu}{\delta^{12}} \left(e^{-\frac{\delta r}{2C_\nu}} + \epsilon^{1/2}\right).
    \end{equation}

1. We recall that $\nu$ is a fixed parameter. In this first step, we set the values the constants $\alpha_\nu$ and $R_\nu$. Let $C_\nu$ be given by Proposition \ref{prop:2}; we set $\alpha_\nu = 300 C_\nu$. We now define $R_\nu$. The quantity $R^{12} e^{-\nu R/2}$ goesto $0$ as $R$ goes to infinity. Therefore, there exists $R_\nu \geq 4$ such that for all $R \geq R_\nu$,
\begin{equation}\label{eq-2e}
    R^{12} e^{-\nu R/2} < \dfrac{1}{2}.
\end{equation}

Fix now $R \geq R_\nu$ (in particular, \eqref{eq-2e} holds); and define 
\begin{equation}\label{eq-2c}
\delta = \alpha_\nu \frac{\ln R}{3 R} = 100 C_\nu \dfrac{\ln R}{R}.
\end{equation}
We will prove that ${\mathcal G} \cap \Sigma(H_e)$ is $3\delta$-dense within ${\mathcal G}$, that is, $\alpha_\nu \frac{\ln R}{R}$-dense within $\Sigma(H_e)$. 

2. Let us assume for now that the following statements hold,
\begin{align}
    (\lambda_*-\delta, \lambda_* + \delta) \cap \Sigma(H_e) = \emptyset,\\
   \label{eq-2d} (\lambda_*-\delta, \lambda_* + \delta) \cap \Sigma(H_+) = \emptyset,\\
    (\lambda_*-\delta, \lambda_* + \delta) \cap \Sigma(H_-) = \emptyset,
\end{align}
and let's aim for a contradiction. Note that these statements imply that $H_e, H_\pm$ satisfy Assumption \ref{a4}. 

Since $\Omega$ has filling radius at least $R$, there exists ${\textbf{n}} \in {\mathbb Z}^2$ such that $B_{8r}({\textbf{n}}) \subset \Omega$, $r = R/8$. We now look at $(H_e-H_+)({\bm{x}},{\bm{y}})$ for ${\bm{x}},{\bm{y}}$ in $B_{4r}({\textbf{n}})$. Because ${\bm{x}}, {\bm{y}} \in \Omega$, we have:
\begin{equation}
    (H_e-H_+)({\bm{x}},{\bm{y}}) = (H_e-\1_\Omega H_+ \1_\Omega - \1_{\Omega^c} H_- \1_{\Omega^c})({\bm{x}},{\bm{y}}) = E({\bm{x}},{\bm{y}}),
\end{equation}
where $E$ is the operator defined in Assumption \ref{a2}. Moreover, 
\begin{equation}
    d({\bm{x}},\partial \Omega) \geq d({\textbf{n}},\partial \Omega) - |{\bm{x}}-{\textbf{n}}| \geq 8r- 4r = 4r,
\end{equation}
because $B_{8r}({\textbf{n}}) = B_R({\textbf{n}}) \subset \Omega$. It follows from \eqref{eq-1a} that 
\begin{equation}
    \big| (H_e-H_+)({\bm{x}},{\bm{y}}) \big| \leq \nu^{-1} e^{- 8\nu r}, \qquad {\bm{x}}, {\bm{y}}\in B_{4r}({\textbf{n}}).
\end{equation}


Proposition \ref{prop:2} then yields
\begin{equation}
    \big| \sigma(H_e,\lambda_*) - \sigma(H_+,\lambda_*) \big| \leq \dfrac{C_\nu}{\delta^{12}} \exp\left(-\dfrac{\delta r}{2C_\nu}\right) + \dfrac{C_\nu \nu^{-1/2}}{\delta^{12}}e^{-4 \nu r}.
\end{equation}
We recall that $\delta$ has the value \eqref{eq-2c}. Therefore, since $C_\nu \geq 1$ and $R \geq R_\nu \geq 4$,
\begin{align}
    \dfrac{C_\nu}{\delta^{12}} \exp\left(-\dfrac{\delta r}{2C_\nu}\right) & = \dfrac{C_\nu R^{12}}{(100 C_\nu \ln R)^{12}} \exp\left(-\dfrac{100 C_\nu \ln R}{R} \cdot \dfrac{R}{16C_\nu}\right) 
    \\
    & \leq R^{12} \exp\left(-\dfrac{25}{4} R\right) \leq R^{-1/2} \leq \dfrac{1}{2}.
\end{align}
The last two inequalities are true for $R\geq 4$. Likewise, because $R$ satisfies \eqref{eq-2e},
\begin{equation}
   \dfrac{C_\nu \nu^{-1/2}}{\delta^{12}}e^{-4\nu r} = \dfrac{C_\nu R^{12}}{(100 C_\nu \ln R)^{12}} \exp\left( -\dfrac{\nu R}{2} \right) \leq R^{12} \exp\left( -\dfrac{\nu R}{2} \right) < \dfrac{1}{2}.
\end{equation}
Going back to \eqref{eq-2d}, we conclude that
\begin{equation}
    \big| \sigma(H_e,\lambda_*) - \sigma(H_+,\lambda_*) \big| < 1. 
\end{equation}
Since bulk conductances are integers (see \cite{EGS05}*{Proposition 3} and Remark \ref{rmk: interger_conductance} below), we conclude that $\sigma(H_e,\lambda_*) = \sigma(H_+,\lambda_*)$.

Similarly, we conclude that $\sigma(H_e,\lambda_*) = \sigma(H_-,\lambda_*)$. This cannot be true, since $\sigma(H_+,\lambda_*) \neq \sigma(H_-,\lambda_*)$. We conclude that for each $\lambda_* \in {\mathcal G}$, one of the statements among \eqref{eq-2d} must fail. In other words, for all $\lambda_* \in {\mathcal G}$, there exists some $\lambda \in \Sigma(H_e) \cup \Sigma(H_+) \cup \Sigma(H_-)$ such that $|\lambda-\lambda_*| \leq \delta$.

It remains to show that $\Sigma(H_e) \cap {\mathcal G}$ is $3\delta$-dense within ${\mathcal G}$. Write ${\mathcal G} = (a,b)$ with $b - a>3\delta$ (otherwise any subset is $3\delta$-dense by definition). Let $\lambda_* \in (a+\delta,b-\delta)$ and $\lambda \in \Sigma(H_e) \cup \Sigma(H_+) \cup \Sigma(H_-)$ such that $|\lambda-\lambda_*| \leq \delta$. In particular, $\lambda \in (a,b) = {\mathcal G}$, which is a spectral gap of $H_\pm$, so $\lambda \in \Sigma(H_e)$. Let now $\lambda_* \in (a,\mu_*)$, $\mu_* = a+2\delta$; since $b-a > 3\delta$, $\mu_* \in (a+\delta,b-\delta)$ and by the previous step there exists $\mu \in \Sigma(H_e)$ such that $|\mu-\mu_*| \leq \delta$. In particular,  $|\mu-\lambda_*| \leq 3\delta$. A similar argument works for $\lambda_* \in (b-2\delta,b)$. We conclude that ${\mathcal G} \cap \Sigma(H_e)$ is $3\delta$-dense within ${\mathcal G}$.

\label{prop: CTthm}\cite{AW15}*{Theorem 10.5}
    Let $H$ be a selfadjoint, short-range operator on $\ell^2({\mathbb Z}^2;{\mathbb C}^d)$. If $\alpha \in (0,2\nu)$ and $z \in {\mathbb C}$ are such that $\Delta := d(z,\Sigma(H)) > S_\alpha$, then we have 
    \begin{equation}
        \label{eq: CTthm_1}
    |(H-z)^{-1}({\bm{x}}, {\bm{y}})|\leq \frac{1}{\Delta- S_\alpha}\exp(-\alpha|{\bm{x}} - {\bm{y}}|).   
    \end{equation}

\label{lem:1a} There exists a constant $C_\nu$, such that for any $H, \lambda$ satisfying Assumption \ref{a4}:
\begin{equation}\label{eq-1i}
     \big| P_\lambda(H)({\bm{x}},{\bm{y}}) \big| \leq \frac{C_\nu}{\delta}\exp\left(-\dfrac{\delta}{C_\nu}|{\bm{x}} - {\bm{y}}|\right).
\end{equation}

Set $\alpha = 2^{-5} \nu^4 \delta$,  so that $\alpha \leq \nu$ 
and $S_\alpha \leq \frac{16\alpha}{\nu^4}\leq \frac{\delta}{2}$, see \eqref{eq-1h}. Let $\gamma$ be a contour enclosing $\Sigma(H) \cap (-\infty,\lambda)$, at least $\delta$-distant from $\Sigma(H)$. For $z \in \gamma$, we have:
\begin{equation}\label{eq-1j}
    (H-z)^{-1}({\bm{x}},{\bm{y}}) \leq \dfrac{e^{-\alpha |{\bm{x}}-{\bm{y}}|}}{\Delta-S_\alpha} \leq \frac{e^{-\alpha |{\bm{x}}-{\bm{y}}|}}{\delta - \frac{\delta}{2}}\leq \frac{2}{\delta}\exp\left(-\alpha|{\bm{x}} - {\bm{y}}|\right). 
\end{equation}
Integrating this over $\gamma$, we have:
\begin{equation}
   \big| P_\lambda(H)({\bm{x}},{\bm{y}}) \big| = \left| \dfrac{1}{2\pi i} \oint_\gamma (H-z)^{-1}({\bm{x}},{\bm{y}}) dz \right| \leq \frac{|\gamma|}{\pi\delta}\exp\left(-\alpha|{\bm{x}} - {\bm{y}}|\right). 
\end{equation}

Without loss of generalities, we may assume that $|\gamma| \leq 2\pi + 4 \| H \|$ -- see Figure \ref{fig:3} 

From the bound \eqref{eq-1g} on $\| H \|$, we deduce that
\begin{equation}\label{eq-1k}
    \dfrac{|\gamma|}{\pi} \leq 2 + \dfrac{16}{\pi\nu^3} \leq \dfrac{8}{\nu^3}.
\end{equation}
We conclude that 
\begin{equation}
    \big| P_\lambda(H)({\bm{x}},{\bm{y}}) \big| \leq \frac{8}{\nu^3\delta}\exp\left(-\dfrac{\nu^4 \delta}{32}|{\bm{x}} - {\bm{y}}|\right).
\end{equation}
 This yields \eqref{eq-1i} (with for instance $C_\nu =32 \nu^{-4}$).

\label{lem:1b} There exists a constant $C_\nu$ such that the following holds. Let $r, \epsilon > 0$, and two triplets $H_1, \lambda, \delta$ and $H_2, \lambda, \delta$ satisfying Assumption \ref{a4}, such that for ${\bm{x}},{\bm{y}} \in B_{4r}(0)$,
\begin{equation}\label{eq-1l}
    |H_1({\bm{x}},{\bm{y}})-H_2({\bm{x}},{\bm{y}})| \leq \epsilon.
\end{equation}
Then for $({\bm{x}},{\bm{y}})$ in $B_{2r}(0)$:
\begin{equation}\label{eq-1n}
    |P_\lambda(H_1)({\bm{x}},{\bm{y}})-P_\lambda(H_2)({\bm{x}},{\bm{y}})| \leq \dfrac{C_\nu}{\delta^6} \left( \exp\left(-\dfrac{\delta r}{C_\nu}\right) + \epsilon \right).
\end{equation}

Let $\alpha, \gamma$ be as in the proof of Lemma \ref{lem:1a}. We have:
\begin{equation}
   \big(P_\lambda(H_1) - P_\lambda(H_2)\big) ({\bm{x}},{\bm{y}}) = \sum_{{\bm{x}}',{\bm{y}}'} \dfrac{1}{2\pi i} \oint_\gamma (H_2-z)^{-1}({\bm{x}},{\bm{x}}') \big( H_2({\bm{x}}',{\bm{y}}') - H_1({\bm{x}}',{\bm{y}}') \big) (H_1-z)^{-1}({\bm{y}}',{\bm{y}}) dz. 
\end{equation}
From \eqref{eq-1j} then \eqref{eq-1k}, and using the bound \eqref{eq-1k} for $|\gamma|$:
\begin{align}
     \big| \big(P_\lambda(H_1) - P_\lambda(H_2)\big) ({\bm{x}},{\bm{y}}) \big| & \leq \dfrac{2|\gamma|}{\pi \delta^2}\sum_{{\bm{x}}',{\bm{y}}'}  \exp\left(-\alpha|{\bm{x}} - {\bm{x}}'|-\alpha|{\bm{y}} - {\bm{y}}'|\right) \big| H_2({\bm{x}}',{\bm{y}}') - H_1({\bm{x}}',{\bm{y}}') \big|
    \\
    & \leq \dfrac{2^4}{\nu^3\delta^2 }\sum_{{\bm{x}}',{\bm{y}}'}  \exp\left(-\alpha|{\bm{x}} - {\bm{x}}'|-\alpha|{\bm{y}} - {\bm{y}}'|\right) \big| H_2({\bm{x}}',{\bm{y}}') - H_1({\bm{x}}',{\bm{y}}') \big|. \label{eq-1f}
\end{align}
We split the RHS sum in two parts, depending whether ${\bm{x}}', {\bm{y}}' \in B_{4r}(0)$ or not. When they do, we can use the bound \eqref{eq-1l} on the kernel of $H_1-H_2$. It yields
\begin{align}
    & \sum_{x',y' \in B_{4r}(0)}  \exp\left(-\alpha|{\bm{x}} - {\bm{x}}'|-\alpha|{\bm{y}} - {\bm{y}}'|\right) \big| H_2(x',y') - H_1(x',y') \big|
    \\
   \leq &  \epsilon \sum_{x',y' \in {\mathbb Z}^2}  \exp\left(-\alpha|{\bm{x}} - {\bm{x}}'|-\alpha|{\bm{y}} - {\bm{y}}'|\right) 
    \\
   \leq & \epsilon \sum_{x',y' \in {\mathbb Z}^2}  \exp\left(-\alpha|{\bm{x}}'|-\alpha|{\bm{y}}'|\right) \leq  \epsilon \left( \dfrac{16}{\alpha^2} \right)^2, 
\end{align}
where in the last line we used \eqref{eq-1e}.

When now restricting to ${\bm{x}}'$ or ${\bm{y}}' \in B_{4r}(0)^c$, we note that for  ${\bm{x}}, {\bm{y}} \in B_{2r}(0)$ either $|{\bm{x}} - {\bm{x}}'| \geq 2r$ or $|{\bm{y}} - {\bm{y}}'| \geq 2r$. Thus, we have
\begin{align}
    & \sum_{{\bm{x}}' \text{ or } {\bm{y}}' \in B_{2r}(0)^c}  \exp\left(-\alpha|{\bm{x}} - {\bm{x}}'|-\alpha|{\bm{y}} - {\bm{y}}'|\right) \big|H_2({\bm{x}}',{\bm{y}}') - H_1({\bm{x}}',{\bm{y}}') \big|
    \\
    \leq &  \dfrac{2}{\nu} \sum_{{\bm{x}}'  \text{ or } {\bm{y}}' \in B_{4r}(0)^c}  \exp\left(-\alpha|{\bm{x}} - {\bm{x}}'|-\alpha|{\bm{y}} - {\bm{y}}'|\right) \leq \dfrac{4}{\nu} \sum_{{\bm{x}}' \in B_{2r}(0)^c, {\bm{y}}' \in {\mathbb Z}^2}  \exp\left(-\alpha|{\bm{x}}'|-\alpha|{\bm{y}}'|\right)
    \\
    & \leq \dfrac{4}{\nu} \left(\frac{32}{\alpha^2}e^{-\alpha r}\right) \left(\frac{16}{\alpha^2}\right) = \frac{8}{\nu} \left(\frac{2^8}{\alpha^4}\right)e^{-\alpha r}.                                                   
\end{align}
In the last line, we applied \eqref{eq-1e}. So, heading back to \eqref{eq-1f} and using the value $\alpha = 2^{-5} \nu^4 \delta$ from the proof of Lemma \ref{lem:1a}, we obtain
\begin{equation}
    \big| \big(P_\lambda(H_1) - P_\lambda(H_2)\big) (x,y) \big| \leq \dfrac{2^7}{\nu^4 \delta^2} \left(\dfrac{2^8}{\alpha^4}\right) (e^{-\alpha r}+\epsilon) = \dfrac{2^{35}}{\nu^{20} \delta^6} \left(\exp\left(-\dfrac{\nu^4 \delta}{32}r\right) + \epsilon\right).
\end{equation}
This yields \eqref{eq-1n} (with $C_\nu = 2^{35}\nu^{-20}$ -- we made no attempts to minimize this constant).

\label{prop:3} Fix $\varepsilon > 0, \ C > 0, \ r >0, \ \beta \in (0,1]$. Let $A_0, A_1, A_2$ be three operators on $\ell^2({\mathbb Z}^2,{\mathbb C}^d)$ with the following properties:
\begin{itemize}
    \item[(i)] For $j \in \{0,1,2\}$, $|A_j({\bm{x}},{\bm{y}})| \leq C e^{-2\beta|x-y|}$;
    \item[(ii)] There exists $k \in \{0,1,2\}$ such that if ${\bm{x}},{\bm{y}} \in B_{2r}(0)$,then $\big| A_k({\bm{x}},{\bm{y}}) \big| \leq C \varepsilon$.
\end{itemize}
Then $B := A_0[A_1,\Lambda_1][A_2,\Lambda_2]$ is trace-class and 
\begin{equation}
   \big| \operatorname{Tr}(B)  \big| \leq  C^3 \frac{2^{16}}{\beta^6} \left(e^{-\beta r} + \varepsilon^{1/2} \right).
\end{equation}

\label{lemma: all} Let $A$ be a bounded operator on $\ell^2({\mathbb Z}^2,{\mathbb C}^d)$ with $|A({\bm{x}},{\bm{y}})| \leq e^{-2\beta |{\bm{x}}-{\bm{y}}|}$. Then 
    \begin{equation}\label{eq-1x}
        \big| [A, \Lambda_1]({\bm{x}}, {\bm{y}}) \big|\leq e^{-2\beta|x_1| - 2\beta|y_1| - 2\beta|x_2 - y_2|}.
    \end{equation}
If moreover $|A({\bm{x}},{\bm{y}})| \leq \varepsilon$ for $({\bm{x}},{\bm{y}}) \in B_{2r}(0)$, then  
     \begin{equation}\label{eq-1y}
        \big| [A, \Lambda_1]({\bm{x}}, {\bm{y}}) \big| \leq \varepsilon^{1/2} e^{-\beta|x_1| - \beta|y_1| - \beta|x_2 - y_2|}, \qquad {\bm{x}},{\bm{y}} \in B_{2r}(0).
    \end{equation}

The kernel of $[A, \Lambda_1]$ is 
\begin{equation}
    [A, \Lambda_1]({\bm{x}}, {\bm{y}}) = A({\bm{x}},{\bm{y}})(\Lambda_1({\bm{y}}) - \Lambda_1({\bm{x}})).
\end{equation}
We note that $|\Lambda_1({\bm{y}}) - \Lambda_1({\bm{x}})| = 0$ if $x_1, y_1$ are both positive or both negative; and it is at most $1$ otherwise, that is if $x_1y_1 \leq 0$. Therefore, we have the bound
\begin{equation}
    \big| [A, \Lambda_1]({\bm{x}}, {\bm{y}})\big| \leq C e^{-2\beta |{\bm{x}}-{\bm{y}}|} \mathbb{1}_{x_1 y_1 \leq 0}.
\end{equation}
Whenever $x_1y_1 \leq 0$, we have
\begin{equation}
    |{\bm{x}}-{\bm{y}}| = |x_1-y_1| + |x_2-y_2| = |x_1| + |y_1| + |x_2-y_2|.
\end{equation}
It follows that 
\begin{equation}
    \big| [A, \Lambda_1]({\bm{x}}, {\bm{y}})  \big| \leq e^{-2\beta |x_2-y_2|-2\beta|x_1|-2\beta|y_1|}.
\end{equation}
This completes the proof of \eqref{eq-1x}. To prove \eqref{eq-1y}, we recall that $|\Lambda_1({\bm{y}}) - \Lambda_1({\bm{x}})| \leq 1$; hence $\big| [A, \Lambda_1]({\bm{x}}, {\bm{y}}) \big| \leq \varepsilon$. It suffices then to interpolate this bound with \eqref{eq-1x}.

1. By a scaling argument, we can assume that $C=1$. We first control the kernel of $B$: 
\begin{equation}
    |B({\bm{x}},{\bm{w}})| = \left| \sum_{y,z \in {\mathbb Z}^2} A_0({\bm{x}},{\bm{y}})B_1({\bm{y}},{\bm{z}})B_2({\bm{z}},{\bm{x}}) \right|,
\end{equation}
where $B_j = [A_j,\Lambda_j]$. We control the kernels of $A_0$, $B_1, B_2$ using assumption $(i)$ and \eqref{eq-1x}. It yields:
\begin{align}
    |B({\bm{x}},{\bm{w}})| & = \left| \sum_{{\bm{y}},{\bm{z}} \in {\mathbb Z}^2} A_0({\bm{x}},{\bm{y}})B_1({\bm{y}},{\bm{z}})B_2({\bm{z}},{\bm{w}}) \right|
    \\
    & \leq \sum_{{\bm{y}},{\bm{z}} \in {\mathbb Z}^2} e^{-2\beta |{\bm{x}}-{\bm{y}}| - 2\beta |y_2-z_2| -2\beta |y_1| - 2\beta |z_1| - 2\beta |z_1-w_1| - 2\beta |z_2| - 2\beta |w_2|} 
    \\
    & \leq \left( \dfrac{4}{\beta} \right)^4 e^{-\beta|{\bm{x}}|-\beta|{\bm{w}}|}.\label{eq-1s}
\end{align}
Thus $|B({\bm{x}},{\bm{w}})|$ decays exponentially, hence $B$ is trace-class; moreover 
\begin{align} 
    \operatorname{Tr}(B) \leq  \sum_{{\bm{x}} \in {\mathbb Z}^2} |B({\bm{x}},{\bm{x}})| \leq & \sum_{{\bm{x}},{\bm{y}},{\bm{z}} \in {\mathbb Z}^2} e^{- 2\beta |{\bm{x}}-{\bm{y}}| - 2\beta |y_2 - z_2| - 2\beta |y_1| - 2\beta |z_1| - 2\beta |z_1 - x_1| - 2\beta |z_2| - 2\beta |x_2|}\\
    := & \sum_{{\bm{x}},{\bm{y}},{\bm{z}} \in {\mathbb Z}^2} f(2\beta, {\bm{x}}, {\bm{y}},{\bm{z}}). \label{eq-1t}
\end{align}

2. We now split the sum in \eqref{eq-1t} in two pieces: $|{\bm{x}}| \geq r$ and $|{\bm{x}}| \leq r$. Thanks to \eqref{eq-1r} and \eqref{eq-1e}, we have 
\begin{equation}
    \sum_{|{\bm{x}}| \geq r} f(2\beta, {\bm{x}}, {\bm{y}},{\bm{z}}) \leq \left( \dfrac{4}{\beta} \right)^4 \sum_{|{\bm{x}}| \geq r} e^{-2\beta|{\bm{x}}|} \leq \left( \dfrac{4}{\beta} \right)^4 \dfrac{8}{\beta^2} e^{-\beta r} = \frac{2^{11}}{\beta^6}e^{-\beta r}.
\end{equation}
We focus below on $|{\bm{x}}| \leq r$. 

3. If $k=0$ in (ii), then we split the sum in \eqref{eq-1t} according to $|{\bm{y}}| \geq 2r$ and $|{\bm{y}}| \leq 2r$. In the former case, $|{\bm{x}}-{\bm{y}}| \geq r$. Therefore, when $|{\bm{x}}| \leq r, \ |{\bm{y}}| \geq 2r$, we deduce that
\begin{align}
    \big| A_0({\bm{x}},{\bm{y}}) \big| & \leq e^{-2\beta|{\bm{x}}-{\bm{y}}|} \leq  e^{-\beta r -\beta|{\bm{x}}-{\bm{y}}|},
  \\
  \big| A_0({\bm{x}},{\bm{y}})B_1({\bm{y}},{\bm{z}})B_2({\bm{z}},{\bm{x}}) \big| & \leq e^{-\beta r} f(\beta,{\bm{x}},{\bm{y}},{\bm{z}}). \label{eq-1v}
\end{align}
If now $|{\bm{y}}| \leq 2r$ (and $|{\bm{x}}| \leq r \leq 2r$), then we can use (ii). Interpolating with (i) gives, for $|{\bm{x}}| \leq r, \ |{\bm{y}}| \leq 2r$:
\begin{align}
    \big| A_0({\bm{x}},{\bm{y}}) \big| & \leq \varepsilon^{1/2} e^{-\beta|{\bm{x}}-{\bm{y}}|}, 
    \\
  \big| A_0({\bm{x}},{\bm{y}})B_1({\bm{y}},{\bm{z}})B_2({\bm{z}},{\bm{x}}) \big| & \leq \varepsilon^{1/2} f(\beta,{\bm{x}},{\bm{y}},{\bm{z}}).\label{eq-1u}
\end{align}
Summing the bounds \eqref{eq-1v} and \eqref{eq-1u} produces:
\begin{align}
    \sum_{\substack{|{\bm{x}}| \leq r, \\ {\bm{y}}, {\bm{z}} \in {\mathbb Z}^2}} \big| A_0({\bm{x}},{\bm{y}})B_1({\bm{y}},{\bm{z}})B_2({\bm{z}},{\bm{x}}) \big| & \leq e^{-\beta r} \sum_{\substack{ |{\bm{x}}| \leq r, \\ |{\bm{y}}| \geq 2r, {\bm{z}} \in {\mathbb Z}^2}} f(\beta,{\bm{x}},{\bm{y}},{\bm{z}}) + \varepsilon^{1/2} \sum_{\substack{|{\bm{x}}| \leq r, \\ |{\bm{y}}| \leq 2r, {\bm{z}} \in {\mathbb Z}^2}} f(\beta,{\bm{x}},{\bm{y}},{\bm{z}})
    \\
    & \leq \left(e^{-\beta r} + \varepsilon^{1/2} \right) \sum_{{\bm{x}},{\bm{y}},{\bm{z}} \in {\mathbb Z}^2}  f(\beta,{\bm{x}},{\bm{y}},{\bm{z}}) 
    \\
    & \leq  \frac{2^{16}}{\beta^6} \left(e^{-\beta r} + \varepsilon^{1/2} \right) . \label{eq-1w}
\end{align}
where we used \eqref{eq-1r} and \eqref{eq-1e} to get
\begin{equation}
    \sum_{{\bm{x}},{\bm{y}},{\bm{z}} \in {\mathbb Z}^2} f(\beta,{\bm{x}},{\bm{y}},{\bm{z}}) \leq  \left(\frac{8}{\beta}\right)^4 \sum_{{\bm{x}} \in {\mathbb Z}^2} e^{-\beta|{\bm{x}}|} \leq \left(\frac{8}{\beta}\right)^4 \frac{16}{\beta^2} = \frac{2^{16}}{\beta^6}. \label{eq-1z}
\end{equation}

4. We now work on $k=1$. We split the sum in ${\bm{y}}, {\bm{z}} \in B_{2r}(0)$ and ${\bm{y}}$ or ${\bm{z}}$ outside $B_{2r}(0)$. In the latter case, either $|{\bm{x}}-{\bm{y}}| \geq r$ or $|{\bm{z}}-{\bm{x}}| \geq r$. So either 
\begin{equation}
    \big|A_0({\bm{x}},{\bm{y}}) \big| \leq e^{-\beta r} e^{-\beta|{\bm{x}}-{\bm{y}}|}  \text{ or } \big| B_2({\bm{z}},{\bm{x}}) \big| \leq e^{-\beta r}  e^{-\beta|{\bm{z}}-{\bm{x}}|}.
\end{equation}
In either case, we recover the bound \eqref{eq-1v}. In the former case, we can use \eqref{eq-1y}, and recover \eqref{eq-1u}. Since \eqref{eq-1v} and \eqref{eq-1u} lead to \eqref{eq-1w}, we obtain this bound here as well. 

5. The case $k=2$ follows the same path as $k=0$ . This completes the proof.

\label{prop:1} Let $H$ be a short-range operator on $\ell^2({\mathbb Z}^2,{\mathbb C}^d)$ and $\lambda \notin \Sigma(H)$. For any ${\textbf{n}}$,
\begin{equation}
    \sigma(H,\lambda) = -2\pi i\operatorname{Tr}\left( P_\lambda(H) \big[ [P_\lambda(H),\Lambda_1(\cdot-n_1)], [P_\lambda(H),\Lambda_2(\cdot-n_2)] \big]\right).
\end{equation}

1. For simplicity, use the notation $P_j = P_\lambda(H_j)$. Let $T$ be the translation by ${\textbf{n}}$: $T u (\cdot)= u(\cdot - {\textbf{n}})$. We have $\Lambda_j(\cdot - n_j) = T \Lambda_j(\cdot) T^*$ and $T^* P_\lambda(H) T = P_\lambda(T^* HT)$. Using these and Proposition \ref{prop:1}, as well as the cyclicity of the trace, we obtain
\begin{align}
    \sigma(H_j,\lambda) & = -2\pi i\operatorname{Tr} \big( P_j \big[ [P_j, T \Lambda_1 T^*], [P_j, T \Lambda_2 T^*] \big] \big)
    \\
    & = -2\pi i\operatorname{Tr} \big(  P_j  \big[ T [ T^* P_j T,  \Lambda_1 ] T^*, T[T^*  P_j T,   \Lambda_2] T^* \big] \big)
    \\
    & = -2\pi i\operatorname{Tr} \big(  P_j   T \big[ [ T^*P_j T,  \Lambda_1 ] , [T^*  P_j T,   \Lambda_2] \big] T^* \big) 
    \\
    & = -2\pi i\operatorname{Tr} \big(  T^* P_j   T \big[ [ T^* P_j T,  \Lambda_1 ] , [T^*  P_j T,   \Lambda_2] \big]  \big) = \sigma(T^* H_j T,\lambda).  
\end{align}
Therefore, by replacing $H_j$ by $T^* H_j T$, we can simply assume that ${\textbf{n}} = 0$. 

2. Now we write 
\begin{equation}\label{eq-2a}
    \sigma(H_1,\lambda)-\sigma(H_2,\lambda) = T(P_1-P_2,P_1,P_1) + T(P_2,P_1-P_2,P_1) + T(P_2,P_2,P_1-P_2), 
\end{equation}
where $T(A_0,A_1,A_2)$ is the trilinear form
\begin{equation}
    T(A_0,A_1,A_2) = -2\pi i \operatorname{Tr}\left( A_0 [A_1,\Lambda_1] [A_2,\Lambda_2]\right) + 2\pi i \operatorname{Tr}\left( A_0 [A_2,\Lambda_2] [A_1,\Lambda_1]\right). 
\end{equation}

From Lemmas \ref{lem:1a} and \ref{lem:1b}, we have (for a constant $C_\nu$ depending on $\nu$ only):
\begin{align}
    \big| P_j({\bm{x}},{\bm{y}}) \big| & \leq \dfrac{C_\nu}{\delta} e^{-\delta |{\bm{x}}-{\bm{y}}|/C_\nu},  \qquad j=1,2;
    \\
    \big| P_1({\bm{x}},{\bm{y}}) - P_2({\bm{x}},{\bm{y}}) \big| & \leq \dfrac{C_\nu}{\delta^6} \left( e^{-\delta |{\bm{x}}-{\bm{y}}|/C_\nu} + \epsilon\right), \qquad {\bm{x}},{\bm{y}} \in B_{2r}({\textbf{n}}).
\end{align}
Therefore, the triplets $(A_0,A_1,A_2)$ involved in \eqref{eq-2a} satisfy the assumptions of Proposition \ref{prop:3}, with constants
\begin{equation}
    C = \dfrac{C_\nu}{\delta}, \quad \beta = \dfrac{\delta}{2 C_\nu}, \quad \varepsilon = \dfrac{1}{\delta^5} \left( e^{-\delta r / C_\nu} + \epsilon\right).
\end{equation}
So, we deduce that
\begin{equation}
    \big|\sigma(H_1,\lambda))-\sigma(H_2,\lambda)\big| \leq \dfrac{C_\nu}{\delta^{3+6}} \left( e^{\frac{\delta r}{2C_\nu}} + \dfrac{1}{\delta^{5/2}} (e^{-\frac{\delta r}{C_\nu}} + \epsilon)^{1/2} \right) \leq \dfrac{C_\nu}{\delta^{12}} \left( e^{-\frac{\delta r}{2C_\nu}} + \epsilon^{1/2} \right).
\end{equation}
This completes the proof of Proposition \ref{prop:2}.

